"""Shared helper functions for scripts generated by the Coder.

Provides load_splits() and load_val_preds_with_labels() to prevent scripts
from guessing file formats or misaligning predictions with ground truth.
"""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any

import pandas as pd


def load_splits(splits_path: str | Path) -> dict[str, Any]:
    """Load splits.json and return its parsed dictionary."""
    path = Path(splits_path)
    if not path.is_file():
        raise FileNotFoundError(f"Splits file not found: {path}")
    return json.loads(path.read_text(encoding="utf-8"))


def load_val_preds_with_labels(
    val_preds_path: str | Path,
    train_data_path: str | Path,
    target_column: str | None = None,
) -> pd.DataFrame:
    """Load validation predictions and align each row with its ground truth label.

    Handles alignment by 'example_id' (row indices in train) or by matching ID column.
    Raises ValueError if 0 rows matched.
    """
    val_path = Path(val_preds_path)
    if not val_path.is_file():
        raise FileNotFoundError(f"Validation predictions not found: {val_path}")
    train_path = Path(train_data_path)
    if not train_path.is_file():
        raise FileNotFoundError(f"Training data not found: {train_path}")

    val_df = pd.read_csv(val_path)
    train_df = pd.read_csv(train_path)

    if len(val_df) == 0:
        raise ValueError(f"Validation predictions file is empty: {val_path}")

    # Determine ground truth target column
    if target_column is not None and target_column in train_df.columns:
        target_col = target_column
    else:
        target_col = train_df.columns[-1]

    # Align predictions with true labels
    if "example_id" in val_df.columns:
        try:
            numeric_ids = pd.to_numeric(val_df["example_id"], errors="coerce")
            if not numeric_ids.isna().any():
                matched_targets = train_df.iloc[numeric_ids.astype(int).values][target_col].values
                val_df["true_label"] = matched_targets
            else:
                raise ValueError("example_id contains non-numeric values")
        except Exception as err:
            common_ids = [c for c in val_df.columns if c in train_df.columns and c != target_col]
            if common_ids:
                id_col = common_ids[0]
                val_df = val_df.merge(train_df[[id_col, target_col]], on=id_col, how="inner")
                val_df = val_df.rename(columns={target_col: "true_label"})
            else:
                raise ValueError(f"Failed to map example_id to train rows: {err}") from err
    else:
        common_ids = [c for c in val_df.columns if c in train_df.columns and c != target_col]
        if common_ids:
            id_col = common_ids[0]
            val_df = val_df.merge(train_df[[id_col, target_col]], on=id_col, how="inner")
            val_df = val_df.rename(columns={target_col: "true_label"})
        else:
            if len(val_df) == len(train_df):
                val_df["true_label"] = train_df[target_col].values
            else:
                raise ValueError(
                    f"Cannot align validation predictions ({len(val_df)} rows) with "
                    f"training data ({len(train_df)} rows): no 'example_id' or shared ID column."
                )

    if len(val_df) == 0:
        raise ValueError(
            "Zero rows matched when merging validation predictions with training labels!"
        )

    if "prediction" not in val_df.columns:
        for c in val_df.columns:
            if c.lower() in ("pred", "predicted", "y_pred", target_col.lower()):
                val_df["prediction"] = val_df[c]
                break

    return val_df


